SELECT (SELECT count(*) FROM(SELECT DISTINCT external_id FROM core_import_rows WHERE import_id=$1) s WHERE NOT EXISTS(SELECT 1 FROM core_transactions t WHERE t.company_id=$2 AND t.account_id=$3 AND t.source_system='dataset_v1' AND t.source_company_id=$4 AND t.external_id=s.external_id)),(SELECT count(DISTINCT operation_date) FROM core_import_rows s WHERE s.import_id=$1 AND NOT EXISTS(SELECT 1 FROM core_balances b WHERE b.company_id=$2 AND b.account_id=$3 AND b.balance_date=s.operation_date));
